                        code: -32602, // Invalid params
                        message: format!("Invalid tools/call params: {}", e),
                        data: Vec::new(),
                    }),
60→                });
            }
        };

        let start = Instant::now();
        debug!("MCP tools/call: agent={}", tool_call.name);

        // Serialize the arguments back to bytes for the agent input
