            // { "content": [{ "type": "text", "text": "<output>" }] }
            let content_response = McpContentResponse {
100→                content: vec![McpContent {
                    r#type: "text".to_string(),
                    text: String::from_utf8_lossy(&result.output).to_string(),
                }],
