/// Build a minimal JSON Schema for an agent's input.
fn build_agent_input_schema(_name: &str, _description: &str) -> Vec<u8> {
    let schema = serde_json::json!({
        "type": "object",
240→        "properties": {
            "input": {
                "type": "string",
                "description": "Input data for the agent"
            }
        }
