        assert!(tracker.is_ok());
    }

    #[tokio::test]
    async fn test_record_sequence() {
        let temp_dir = TempDir::new().unwrap();
        let config = PatternTrackerConfig {
            promotion_threshold: 2,
            ..Default::default()
        };
        let tracker = PatternTracker::new(temp_dir.path().to_path_buf(), config)
            .await
