        // First call - no promotion
        let result = tracker
            .record_sequence(&["agent_a", "agent_b"], "hash1", 100)
            .unwrap();
        assert!(result.is_none());

        // Second call - should suggest promotion
        let result = tracker
            .record_sequence(&["agent_a", "agent_b"], "hash2", 150)
            .unwrap();
        assert!(result.is_some());
    }

    #[tokio::test]
