            s -= (agent.priority as i64) * 50;

            // Prefer parallelizable if parallel is allowed
            if request.allow_parallel && agent.parallelizable {
                s += 25;
300→            }

            s
        };

        viable.sort_by_key(|b| std::cmp::Reverse(score(b)));

        viable.first().map(|a| (*a).clone())
