    // requested node by passing its id + 2 (also used by MPOL_PREFERRED).
    let maxnode = nodes
        .iter()
        .copied()
        .max()
        .context("empty NUMA node mask")? as usize
50→        + 2;
    Ok((words, maxnode))
}

fn permitted_cpus(requested: &[u32], allowed: &[u32]) -> Result<Vec<u32>> {
