fn read_cpu_affinity_mask() -> Result<Vec<libc::c_ulong>> {
    let word_bytes = std::mem::size_of::<libc::c_ulong>();
    let mut words = vec![0 as libc::c_ulong; 128 / word_bytes];
    loop {
